import{_ as o,C as r,c as s,o as a,a3 as i,b as l,w as n,a as d,G as c,a4 as m}from"./chunks/framework.Dk6sf0Ip.js";const g=JSON.parse('{"title":"Mantenimiento","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/index.md","filePath":"flows/Mantenimiento/index.md","lastUpdated":1759323946000}'),u={name:"flows/Mantenimiento/index.md"};function A(h,e,C,p,b,f){const t=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=i('<h1 id="mantenimiento" tabindex="-1">Mantenimiento <a class="header-anchor" href="#mantenimiento" aria-label="Permalink to &quot;Mantenimiento&quot;">​</a></h1><p>El Flujo de Mantenimiento de Unidades y Cubiertas organiza todas las acciones desde la detección de una necesidad (checklist inicial) hasta el archivo final de la orden de trabajo.</p><h2 id="su-proposito-es" tabindex="-1">Su propósito es: <a class="header-anchor" href="#su-proposito-es" aria-label="Permalink to &quot;Su propósito es:&quot;">​</a></h2><ul><li>Garantizar la trazabilidad de cada intervención, ya sea preventiva o correctiva.</li><li>Definir responsabilidades: el Operario de Mantenimiento ejecuta el trabajo, mientras que el Auxiliar Administrativo gestiona la documentación y abastecimiento.</li><li>Controlar calidad: mediante la verificación de OT, asegurando que las tareas (montajes, rotaciones, reparaciones de cubiertas, etc.) se cumplieron correctamente.</li><li>Cerrar el ciclo con la imputación de costos y el archivo, manteniendo actualizado el historial de la unidad y de las cubiertas.</li></ul><h2 id="diagrama" tabindex="-1">Diagrama <a class="header-anchor" href="#diagrama" aria-label="Permalink to &quot;Diagrama&quot;">​</a></h2>',5)),(a(),l(m,null,{default:n(()=>[c(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0AA%5B%2220.1.01%20Monitoreo%3Cbr%2F%3EChecklist%3Cbr%2F%3E%22%5D%3A%3A%3Ainicio%20--%3E%20B%7B%22%C2%BFQu%C3%A9%20vas%3Cbr%2F%3Ea%20realizar%3F%22%7D%3A%3A%3Adecision%0A%20%20%20%20B%20--%3E%7CCubiertas%7C%20C%5B%2220.2.08%20Mant.%20Cubiertas%3Cbr%2F%3EPlanificado%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%2220.2.09%20Archivo%20Mant.%3Cbr%2F%3ECubierta%22%5D%3A%3A%3Afinal%0A%20%20%20%20B%20--%3E%7CMantenimiento%7C%20E%5B%2220.2.01%20Orden%3Cbr%2F%3EAbastec.%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%2220.2.04%20OT%3Cbr%2F%3EVerific.%22%5D%3A%3A%3Adecision%0A%20%20%20%20F%20--%3E%7CNo%20OK%7C%20G%5B%2220.2.02%20OT%3Cbr%2F%3EAbierta%22%5D%0A%20%20%20%20G%20--%3E%20F%0A%20%20%20%20F%20--%3E%7COK%7C%20H%5B%22Cerrar%20OT%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%2220.2.06%20Archivo%20Mant.%3Cbr%2F%3ECorrect.%3Cbr%2F%3E%22%5D%3A%3A%3Afinal%0A%20%20%20%20B%20--%3E%7CNo%20corresponde%7C%20J%5B%2220.1.04%20Mant.%3Cbr%2F%3ESuspend.%22%5D%3A%3A%3Afinal%0A%0A%20%20%20%20%25%25%20Leyenda%0A%20%20%20%20subgraph%20Leyenda%0A%20%20%20%20%20%20%20%20L1%5BInicio%5D%3A%3A%3Ainicio%0A%20%20%20%20%20%20%20%20L2%5BDecisi%C3%B3n%5D%3A%3A%3Adecision%0A%20%20%20%20%20%20%20%20L3%5BFinalizaci%C3%B3n%5D%3A%3A%3Afinal%0A%20%20%20%20end%0AclassDef%20inicio%20fill%3A%234ade80%2Cstroke%3A%2322c55e%2Cstroke-width%3A2px%2Ccolor%3A%23000%0AclassDef%20decision%20fill%3A%2360a5fa%2Cstroke%3A%233b82f6%2Cstroke-width%3A2px%2Ccolor%3A%23000%0AclassDef%20final%20fill%3A%23fb923c%2Cstroke%3A%23f97316%2Cstroke-width%3A2px%2Ccolor%3A%23000%0A%0Aclick%20A%20%22.%2F20.1.01_Monitoreo-Checklist%22%0Aclick%20C%20%22.%2FDetalledeMantenimientodeCubiertas.md%22%0Aclick%20E%20%22.%2F20.2.01-Orden-de-abastecimiento_Markdown.md%22%0Aclick%20F%20%22.%2FOT_Verificacion.md%22%0A"})]),fallback:n(()=>e[0]||(e[0]=[d(" Loading... ")])),_:1})),e[2]||(e[2]=i('<h2 id="resumen-del-flujo-de-mantenimiento" tabindex="-1">Resumen del Flujo de Mantenimiento <a class="header-anchor" href="#resumen-del-flujo-de-mantenimiento" aria-label="Permalink to &quot;Resumen del Flujo de Mantenimiento&quot;">​</a></h2><p>El proceso inicia siempre en el <strong>Monitoreo – Checklist (20.1.01)</strong>.<br> Desde ahí se distinguen dos caminos principales:</p><h3 id="mantenimiento-preventivo" tabindex="-1">Mantenimiento preventivo <a class="header-anchor" href="#mantenimiento-preventivo" aria-label="Permalink to &quot;Mantenimiento preventivo&quot;">​</a></h3><ul><li>Es registrado directamente por el <strong>Operario de Mantenimiento (Cristian)</strong>.</li><li>Cuando corresponde, se continúa con el <strong>Mantenimiento Planificado de cubiertas (20.2.08)</strong>.</li><li>Al finalizar, se archiva en <strong>Archivo mantenimiento cubierta (20.2.09)</strong>.</li></ul><h3 id="otros-mantenimientos-de-unidad-cubiertas-u-otros" tabindex="-1">Otros mantenimientos de unidad (cubiertas u otros) <a class="header-anchor" href="#otros-mantenimientos-de-unidad-cubiertas-u-otros" aria-label="Permalink to &quot;Otros mantenimientos de unidad (cubiertas u otros)&quot;">​</a></h3><ul><li>El <strong>Operario</strong> completa la planilla y la pasa al <strong>Auxiliar Administrativo</strong>.</li><li>El Auxiliar gestiona la <strong>Orden de Abastecimiento (20.2.01)</strong>.</li><li>Se realiza la <strong>Verificación de la OT (20.2.04)</strong>.</li><li>Si el trabajo no es correcto, la <strong>OT se abre nuevamente (20.2.02)</strong>.</li><li>Una vez cerrado correctamente, se archiva en <strong>Archivo de mantenimiento correctivo (20.2.06)</strong>.</li></ul><h3 id="casos-especiales" tabindex="-1">Casos especiales <a class="header-anchor" href="#casos-especiales" aria-label="Permalink to &quot;Casos especiales&quot;">​</a></h3><ul><li>En casos donde la acción no corresponde, se registra como <strong>Mantenimiento Suspendido (20.1.04)</strong>.</li></ul><p>Para más detalle ver:</p><ul><li><a href="./20.1.01_Monitoreo-Checklist.html">20.1.01 Monitoreo – Checklist</a></li><li><a href="./DetalledeMantenimientodeCubiertas.html">20.2.03 Mantenimiento Cubiertas</a></li><li><a href="./20.2.01-Orden-de-abastecimiento_Markdown.html">20.2.01 Orden de Abastecimiento</a></li><li><a href="./OT_Verificacion.html">20.2.04 OT Verificación</a></li></ul>',10))])}const E=o(u,[["render",A]]);export{g as __pageData,E as default};
